<script setup>
import {computed,onMounted,onUnmounted,ref} from 'vue';
import {createRoutingClient,moveGateway,readRoutingSnapshot,canApplyPreview,notificationJobMessage} from '@/utilities/routingApi.js';
const api=createRoutingClient(window.location.pathname.replace(/\/$/,''));
const tab=ref('gateways'),busy=ref(false),error=ref(''),notice=ref(''),revision=ref(0);
const state=ref({stale:true,agent_available:false}),gateways=ref([]),entries=ref([]),map=ref([]),events=ref([]),preview=ref(null);
const policy=ref({ordered_gateway_ids:[],failback:true,interval_seconds:10,failure_threshold:3,recovery_threshold:12});
const route=ref({kind:'domain',value:'',comment:''}),query=ref(''),profile=ref(''),gatewayName=ref('');
const binding=ref({enabled:false}),job=ref(null);let jobTimer,disposed=false;
const ordered=computed(()=>[...policy.value.ordered_gateway_ids.map(id=>gateways.value.find(g=>g.id===id)).filter(Boolean),...gateways.value.filter(g=>!policy.value.ordered_gateway_ids.includes(g.id))]);
const filtered=computed(()=>entries.value.filter(r=>(r.value+' '+r.comment).toLowerCase().includes(query.value.toLowerCase())));
async function action(fn){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){error.value=e.status===412?'Черновик изменён в другой сессии. Обновите данные перед повтором.':e.status===503?'Контроллер недоступен. Состояние VPN не изменено.':e.message}finally{busy.value=false}}
async function refresh(){const snapshot=await readRoutingSnapshot(api);state.value=snapshot.status;gateways.value=snapshot.gateways;entries.value=snapshot.routes;policy.value=snapshot.policy;revision.value=snapshot.revision;preview.value=null}
async function savePolicy(){await action(async()=>{await api.request('/policy',{method:'PUT',body:policy.value,revision:revision.value});await refresh();notice.value='Очередь сохранена в черновике.'})}
async function changeGateway(g,body){await action(async()=>{await api.request('/gateways/'+g.id,{method:'PATCH',body,revision:revision.value});await refresh()})}
async function removeGateway(g){await action(async()=>{await api.request('/gateways/'+g.id,{method:'DELETE',revision:revision.value});await refresh();notice.value='Шлюз удалён из черновика. Работающий туннель изменится только после применения.'})}
async function addRoute(){await action(async()=>{await api.request('/route-entries',{method:'POST',body:route.value,revision:revision.value});route.value={kind:'domain',value:'',comment:''};await refresh()})}
async function removeRoute(r){await action(async()=>{await api.request('/route-entries/'+r.id,{method:'DELETE',revision:revision.value});await refresh()})}
async function importProfile(){await action(async()=>{await api.request('/gateways/import',{method:'POST',body:{name:gatewayName.value,profile:profile.value},revision:revision.value});profile.value='';gatewayName.value='';await refresh();notice.value='Шлюз добавлен в черновик. Туннель будет создан только после применения.'})}
async function selectTab(value){tab.value=value;if(value==='map'&&state.value.agent_available)await action(async()=>{map.value=(await api.request('/routes')).items||[]});if(value==='events')await action(async()=>{events.value=(await api.request('/events')).items||[]});if(value==='notifications')await action(async()=>{binding.value=await api.request('/notifications/telegram')})}
async function makePreview(){await action(async()=>{preview.value=await api.request('/previews',{method:'POST',body:{revision:revision.value},revision:revision.value})})}
async function applyPreview(){await action(async()=>{const result=await api.request('/operations',{method:'POST',body:{preview_id:preview.value.preview_id,hash:preview.value.hash},revision:revision.value});notice.value='Операция '+result.operation_id+' принята. Следите за результатом в журнале.';preview.value=null})}
async function pollNotification(id,attempt=0){
 if(disposed)return;
 try{job.value=await api.request('/notifications/jobs/'+id);notice.value=notificationJobMessage(job.value);
  if(!['delivered','succeeded','failed','recovery_required'].includes(job.value.phase)&&attempt<30)jobTimer=setTimeout(()=>pollNotification(id,attempt+1),2000);
  if(job.value.kind==='disable'&&job.value.phase==='succeeded')binding.value=await api.request('/notifications/telegram');
 }catch(e){error.value='Не удалось обновить статус задания. Подтверждения отправки пока нет.'}
}
async function notifyAction(kind){await action(async()=>{clearTimeout(jobTimer);const result=await api.request('/notifications/telegram/'+kind,{method:'POST',body:{}});job.value={job_id:result.job_id,phase:'queued',kind};notice.value=notificationJobMessage(job.value);jobTimer=setTimeout(()=>pollNotification(result.job_id),500)})}
onUnmounted(()=>{disposed=true;clearTimeout(jobTimer)});
onMounted(()=>action(refresh));
</script>
<template>
<section class="routing-page p-3 p-md-4">
 <header class="d-flex flex-wrap justify-content-between gap-3 mb-4"><div><h1 class="h3">Маршрутизация VPN</h1><p class="text-muted mb-0">Шлюзы, очередь переключения и карта адресов</p></div><button class="btn btn-outline-secondary" :disabled="busy" @click="action(refresh)">Обновить</button></header>
 <div v-if="error" role="alert" class="alert alert-danger">{{error}}</div><div v-if="notice" role="status" class="alert alert-success">{{notice}}</div>
 <div class="row g-3 mb-4"><div class="col-md-4"><div class="card p-3 h-100"><small>Ведущий шлюз</small><strong>{{gateways.find(g=>g.id===state.active_gateway_id)?.name || (state.stale?'Нет свежих данных':'Трафик заблокирован')}}</strong></div></div><div class="col-md-4"><div class="card p-3 h-100"><small>Конфигурация</small><strong>Черновик {{revision}} · применена {{state.applied_revision??'неизвестно'}}</strong></div></div><div class="col-md-4"><div class="card p-3 h-100"><small>Контроллер</small><strong>{{state.agent_available?'Доступен':'Недоступен'}}</strong></div></div></div>
 <nav aria-label="Разделы маршрутизации" class="d-flex gap-2 flex-wrap mb-4"><button v-for="[id,title] in [['gateways','Шлюзы'],['map','Карта маршрутов'],['events','Операции'],['notifications','Уведомления']]" :key="id" class="btn" :class="tab===id?'btn-primary':'btn-outline-secondary'" :aria-pressed="tab===id" @click="selectTab(id)">{{title}}</button></nav>
 <fieldset :disabled="busy" class="border-0 p-0">
 <div v-if="tab==='gateways'">
  <h2 class="h5">Порядок переключения</h2><p class="text-muted">Первый здоровый шлюз в очереди имеет наивысший приоритет.</p>
  <ol class="list-unstyled"><li v-for="(g,i) in ordered" :key="g.id" class="card p-3 mb-2"><div class="d-flex flex-wrap align-items-center gap-3"><span class="badge text-bg-secondary">{{g.enabled?i+1:'—'}}</span><div class="flex-grow-1"><strong>{{g.name}}</strong><div class="small text-muted">{{g.endpoint_host}}:{{g.endpoint_port}}</div></div><span v-if="state.active_gateway_id===g.id" class="badge text-bg-success">Ведущий</span><button class="btn btn-sm btn-outline-secondary" :aria-label="'Поднять '+g.name" :disabled="!g.enabled||i===0" @click="policy.ordered_gateway_ids=moveGateway(policy.ordered_gateway_ids,g.id,-1)">↑</button><button class="btn btn-sm btn-outline-secondary" :aria-label="'Опустить '+g.name" :disabled="!g.enabled||i>=policy.ordered_gateway_ids.length-1" @click="policy.ordered_gateway_ids=moveGateway(policy.ordered_gateway_ids,g.id,1)">↓</button><button class="btn btn-sm btn-outline-secondary" @click="changeGateway(g,{enabled:!g.enabled})">{{g.enabled?'Отключить':'Включить'}}</button><button class="btn btn-sm btn-outline-danger" @click="removeGateway(g)">Удалить из черновика</button></div></li></ol>
  <label class="d-block mb-3"><input type="checkbox" v-model="policy.failback"> Возвращаться на более приоритетный шлюз после восстановления</label><button class="btn btn-primary" @click="savePolicy">Сохранить очередь</button>
  <details class="card p-3 mt-4"><summary>Добавить VPN-шлюз</summary><p class="small mt-3">Импортируйте клиентский профиль уже настроенного VPN-сервера. Импорт не создаёт сервер и не меняет работающие туннели.</p><form class="mt-3" @submit.prevent="importProfile"><label class="form-label d-block">Название<input class="form-control" v-model="gatewayName" maxlength="80" required></label><label class="form-label d-block">Профиль AmneziaWG<textarea class="form-control font-monospace" v-model="profile" rows="7" maxlength="65536" required autocomplete="off" spellcheck="false"></textarea></label><button class="btn btn-primary" :disabled="!state.agent_available||!state.capabilities?.profile_import">Проверить и импортировать</button><p v-if="!state.agent_available||!state.capabilities?.profile_import" class="small mt-2">Импорт доступен после подготовки хранилища ключей и проверки исходных шлюзов.</p></form></details>
 </div>
 <div v-if="tab==='map'">
  <div class="card p-3 mb-4"><h2 class="h5">Путь трафика</h2><div class="route-path">LAN / wgs / wgr <span aria-hidden="true">→</span> Карта адресов <span aria-hidden="true">→</span> {{gateways.find(g=>g.id===state.active_gateway_id)?.name || 'Нет подтверждённого выхода'}}</div><p class="small text-muted mb-0 mt-2">При отказе всех выходов адреса карты блокируются.</p></div>
  <form class="row g-2 mb-4" @submit.prevent="addRoute"><div class="col-md-2"><label class="form-label">Тип<select v-model="route.kind" class="form-select"><option value="domain">Домен</option><option value="ipv4">IPv4</option><option value="cidr">Подсеть CIDR</option></select></label></div><div class="col-md-4"><label class="form-label d-block">Адрес<input class="form-control" v-model="route.value" required placeholder="example.org"></label></div><div class="col-md-4"><label class="form-label d-block">Комментарий<input class="form-control" v-model="route.comment" maxlength="500"></label></div><div class="col-md-2 align-self-end pb-2"><button class="btn btn-primary">Добавить</button></div></form>
  <label class="form-label d-block">Поиск<input class="form-control" v-model="query" type="search"></label><div class="table-responsive"><table class="table"><thead><tr><th>Адрес</th><th>Тип</th><th>Комментарий</th><th>Действие</th></tr></thead><tbody><tr v-for="r in filtered" :key="r.id"><td>{{r.value}}</td><td>{{r.kind}}</td><td>{{r.comment}}</td><td><button class="btn btn-sm btn-outline-danger" @click="removeRoute(r)">Удалить</button></td></tr><tr v-if="!filtered.length"><td colspan="4">Ручных записей нет</td></tr></tbody></table></div>
  <details><summary>Наблюдаемая карта и источники</summary><p v-if="!state.agent_available">Нет свежих данных от агента.</p><ul v-else><li v-for="r in map" :key="r.network">{{r.network}} · {{r.sources}}</li></ul></details>
 </div>
 <div v-if="tab==='events'"><h2 class="h5">Журнал операций</h2><p v-if="!events.length" class="text-muted">Нет загруженных событий.</p><ol><li v-for="event in events" :key="event.id">{{event.happened_at}} · {{event.type}} · {{event.phase}}</li></ol></div>
 <div v-if="tab==='notifications'"><h2 class="h5">Telegram через Zabbix</h2><p>При изменении ведущего узла сообщение отправляет существующий Zabbix.</p><p>Состояние: {{binding.status==='configured'?'Настроен':(binding.status||'Не проверено')}}</p>
  <dl v-if="binding.action_id" class="row"><dt class="col-sm-4">Канал</dt><dd class="col-sm-8">{{binding.media_name}}</dd><dt class="col-sm-4">Получатель</dt><dd class="col-sm-8">{{binding.recipient_name}}</dd><dt class="col-sm-4">Чат</dt><dd class="col-sm-8">{{Array.isArray(binding.chat_id)?binding.chat_id.join(', '):binding.chat_id}}</dd><dt class="col-sm-4">Уведомления</dt><dd class="col-sm-8">{{binding.enabled?'Включены':'Отключены'}}</dd></dl>
  <p v-if="binding.capabilities&&!binding.capabilities.new_channel" class="text-muted">Используется существующий канал. Настройка нового бота или получателя ещё не включена в этой версии.</p>
  <div class="d-flex gap-2 flex-wrap"><button class="btn btn-outline-primary" @click="notifyAction('check')">Проверить подключение</button><button class="btn btn-outline-secondary" :disabled="!binding.enabled||!binding.channel_enabled" @click="notifyAction('test')">Отправить тест через Zabbix</button><button class="btn btn-outline-danger" :disabled="!binding.enabled" @click="notifyAction('disable')">Отключить уведомления о переключении</button></div>
  <p v-if="job" class="mt-3" role="status">{{notificationJobMessage(job)}}</p>
 </div>
 </fieldset>
 <footer class="card p-3 mt-4"><div class="d-flex justify-content-between flex-wrap gap-3 align-items-center"><div><strong>Изменения сохраняются в черновике</strong><p class="small text-muted mb-0">Перед применением — просмотр diff и независимый автооткат.</p></div><button class="btn btn-primary" :disabled="busy||!state.agent_available||!state.capabilities?.configuration_apply" @click="makePreview">Проверить изменения</button></div><div v-if="preview" class="mt-3"><pre class="preview">{{JSON.stringify(preview.diff||preview,null,2)}}</pre><button class="btn btn-warning" :disabled="busy||!canApplyPreview(preview)" @click="applyPreview">Применить с автооткатом</button></div></footer>
</section>
</template>
<style scoped>
.routing-page{max-width:1200px;margin:auto}.route-path{display:flex;gap:1rem;align-items:center;flex-wrap:wrap}.preview{white-space:pre-wrap;max-height:24rem;overflow:auto}small{display:block;color:var(--bs-secondary-color)}.form-label{width:100%}fieldset:disabled{opacity:.7}
</style>
